customElements.define('advanced-search',class extends HTMLElement{constructor(){super();this.SEARCH_INPUT='[data-search-input]';this.CLEAR_INPUT='[data-clear-input]';this.FILTER_TOGGLE='[data-search-filter]';this.CLEAR_ALL_FILTERS='[data-clear-all-filters]';this.CLEAR_FILTERS_GROUP='[data-clear-group-filters]';this.RESET_SEARCH='[data-search-reset]';this.debounceTime=500;this.searchDocs=[];this.results=[];this.activeFilters={type:[],regions:[],themes:[],search_species:[],subtopics:[]};this.totalPages=1;this.currentPage=1;this.hasSearchInput=!1;this.hasFilters=!1}
connectedCallback(){this.miniSearch=new window.MiniSearch({fields:['title','description'],storeFields:['title','type','description','date','url','regions','themes','search_species','subtopics'],searchOptions:{boost:{title:2},prefix:!0,fuzzy:2}});this.setupComponent()}
setupComponent(){this.searchDataSelector=this.getAttribute('search-data');if(!this.searchDataSelector){console.warn('advanced-search: Missing "search-data" attribute!');return}
this.searchContainerSelector=this.getAttribute('search-container');this.resultTemplateSelector=this.getAttribute('result-template');this.noResultsSelector=this.getAttribute('no-results');this.resultsPerPage=parseInt(this.getAttribute('results-per-page'),10);this.pageIndexSummarySelector=this.getAttribute('page-summary');this.pageResultSummarySelector=this.getAttribute('results-summary');this.pageControlsSelector=this.getAttribute('page-controls');this.pageProgressSelector=this.getAttribute('pagination-progress');this.searchIndexElement=document.querySelector(this.searchDataSelector);if(!this.searchIndexElement){console.warn(`advanced-search: Could not find script element with ID "${this.searchDataSelector}".`);return}else{try{const parsedJSON=JSON.parse(this.searchIndexElement.textContent);this.searchDocs=parsedJSON.map((item,index)=>({...item,id:index}));this.initializeSearch(this.searchDocs)}catch(error){console.error('advanced-search: Failed to parse JSON data.',error)}}
this.searchInputElement=this.querySelector(this.SEARCH_INPUT);this.clearInputBtnElement=this.querySelector(this.CLEAR_INPUT);this.searchFilterElements=Array.from(this.querySelectorAll(this.FILTER_TOGGLE));this.clearToggleGroupElements=Array.from(this.querySelectorAll(this.CLEAR_FILTERS_GROUP));this.clearToggleGroupElements.forEach(clearBtn=>{clearBtn.classList.add("hide")});this.clearAllTogglesBtnElement=this.querySelector(this.CLEAR_ALL_FILTERS);this.hasSearchInput=!!this.searchInputElement;this.hasFilters=this.searchFilterElements.length>0;this.searchContainerElement=document.querySelector(this.searchContainerSelector);this.resultTemplateElement=document.querySelector(this.resultTemplateSelector);this.noResultsElement=document.querySelector(this.noResultsSelector);this.noResultsElement.style.display="none";this.pageIndexSummaryText=document.querySelector(this.pageIndexSummarySelector);this.pageResultSummaryText=document.querySelector(this.pageResultSummarySelector);this.pageNextBtn=document.querySelector(`${this.pageControlsSelector} [data-page-next]`);this.pagePreviousBtn=document.querySelector(`${this.pageControlsSelector} [data-page-previous]`);this.pageProgressBar=document.querySelector(this.pageProgressSelector);this.setupListeners()}
setupListeners(){this.querySelector('form').addEventListener('keydown',(e)=>{if(e.key==='Enter'){e.preventDefault()}});if(this.hasSearchInput){let timer;this.searchInputElement.addEventListener('input',()=>{clearTimeout(timer);timer=setTimeout(()=>{this.executeSearch()},this.debounceTime)});if(this.clearInputBtnElement){this.clearInputBtnElement.addEventListener('click',()=>{this.clearSearchInput()})}}
if(this.hasFilters){this.searchFilterElements.forEach(toggle=>{toggle.addEventListener('click',(e)=>{this.updateActiveFilters(e);this.executeSearch()})});this.clearToggleGroupElements.forEach(toggle=>{toggle.addEventListener('click',(e)=>{this.clearFilterCategory(e)})});if(this.clearAllTogglesBtnElement){this.clearAllTogglesBtnElement.addEventListener('click',()=>{this.clearAllFilters()})}}
if(this.pageNextBtn){this.pageNextBtn.addEventListener('click',()=>{this.goToNextPage()})}
if(this.pagePreviousBtn){this.pagePreviousBtn.addEventListener('click',()=>{this.goToPreviousPage()})}
if(window.location.search){this.setDefaultSearchFromURL()}
this.executeSearch()}
initializeSearch(searchDocuments){if(Array.isArray(searchDocuments)){this.miniSearch.addAll(searchDocuments)}}
executeSearch(){const query=this.searchInputElement.value.toLowerCase().trim();if(query===""){this.results=this.searchDocs.filter(item=>{return this.checkResultAgainstActiveFilters(item)})}else{this.results=this.miniSearch.search(query,{filter:(result)=>{return this.checkResultAgainstActiveFilters(result)}})}
this.buildURLEndpoint();this.toggleNoResults();this.updatePaginationResults(this.results)}
checkResultAgainstActiveFilters(result){return Object.entries(this.activeFilters).every(([category,activeTags])=>{if(activeTags.length===0)
return!0;const resultCategoryTags=result[category];if(Array.isArray(resultCategoryTags)){return resultCategoryTags.some(tag=>activeTags.includes(tag))}
return activeTags.includes(resultCategoryTags)})}
setDefaultSearchFromURL(){const searchQueryString=decodeURIComponent(window.location.search);const searchParameters=new URLSearchParams(searchQueryString);this.searchInputElement.value=searchParameters.get("query")||"";Object.keys(this.activeFilters).forEach(category=>{if(searchParameters.has(category)){const value=searchParameters.get(category);this.activeFilters[category]=value?value.split(","):[]}});this.setFilterToggles()}
clearSearchInput(){this.searchInputElement.value="";this.executeSearch()}
updateActiveFilters(e){const{name,value}=e.currentTarget;const currentCategory=this.activeFilters[name];const tagIndex=currentCategory.indexOf(value);if(tagIndex>-1){currentCategory.splice(tagIndex,1)}else{currentCategory.push(value)}
this.toggleClearGroupButton(currentCategory.length,name)}
setFilterToggles(){Object.entries(this.activeFilters).forEach(([category,tags])=>{const categoryBtns=this.searchFilterElements.filter(toggle=>{return toggle.name===category});tags.forEach(tag=>{categoryBtns.forEach((toggle)=>{if(toggle.value===tag)
toggle.checked=!0})});this.toggleClearGroupButton(tags.length,category)})}
clearFilterCategory(e){const{name}=e.currentTarget;const currentCategory=this.activeFilters[name];const categoryBtns=this.searchFilterElements.filter(toggle=>{return toggle.name===name});categoryBtns.forEach(toggle=>{toggle.checked=!1});currentCategory.length=0;this.toggleClearGroupButton(currentCategory.length,name);this.executeSearch()}
clearAllFilters(){this.searchFilterElements.forEach(toggle=>{toggle.checked=!1});Object.keys(this.activeFilters).forEach(category=>{this.activeFilters[category].length=0;this.toggleClearGroupButton(0,category)});this.executeSearch()}
updatePaginationResults(results){if(!Array.isArray(results))
return;this.totalPages=Math.ceil(results.length/this.resultsPerPage);this.currentPage=1;this.displayPage(this.currentPage)}
displayPage(page){const startIndex=(page-1)*this.resultsPerPage;const endIndex=Math.min(startIndex+this.resultsPerPage,this.results.length);const pageItems=this.results.slice(startIndex,endIndex);this.renderPageResults(pageItems,startIndex,endIndex)}
renderPageResults(results,startIndex,endIndex){this.searchContainerElement.innerHTML='';const pageFragment=new DocumentFragment();results.forEach(result=>{const resultCard=this.resultTemplateElement.content.cloneNode(!0);const itemType=result.type.toLowerCase().trim();resultCard.querySelector("[data-serach-item]").classList.add(itemType);const titleElement=resultCard.querySelector("[data-item-title]");titleElement.textContent=result.title;titleElement.href=result.url;resultCard.querySelector("[data-item-type]").textContent=result.type;const iconElement=resultCard.querySelector("[data-item-icon]");const iconClasses=this.getResourceTypeIcon(itemType).split(",");iconClasses.forEach(iconClass=>{iconElement.classList.add(iconClass)});const[year,month,day]=result.date.split("-");const usDate=new Date(`${month}-${day}-${year}`);const displayDateFormatter=new Intl.DateTimeFormat('en-US',{month:'long',day:'numeric',year:'numeric'});resultCard.querySelector("[data-item-date]").textContent=displayDateFormatter.format(usDate);resultCard.querySelector("[data-item-description]").textContent=result.description;resultCard.querySelector("[data-item-link]").href=result.url;pageFragment.appendChild(resultCard)});this.searchContainerElement.appendChild(pageFragment);this.updatePaginationControls();this.updatePaginationSummary(startIndex,endIndex)}
getResourceTypeIcon(type){switch(type){case "web-application":return"fa-solid,fa-globe";break;case "data-and-code":return"fa-solid,fa-database";break;case "publication":return"fa-solid,fa-newspaper";break;case "code-repo":return"fa-brands,fa-github";break;case "presentation":return"fa-solid,fa-person-chalkboard";break;default:return"fa-regular,fa-circle-question";break}}
goToNextPage(){if(this.currentPage<this.totalPages){this.currentPage++;this.displayPage(this.currentPage)}}
goToPreviousPage(){if(this.currentPage>1){this.currentPage--;this.displayPage(this.currentPage)}}
toggleClearGroupButton(count,name){const clearGroupBtn=this.getClearToggleGroupBtn(name);if(count>0){if(clearGroupBtn.classList.contains("hide")){clearGroupBtn.classList.remove("hide");clearGroupBtn.removeAttribute("disabled")}}else{clearGroupBtn.classList.add("hide");clearGroupBtn.setAttribute("disabled","")}}
toggleNoResults(){if(this.results.length===0){this.noResultsElement.style.display=""}else{this.noResultsElement.style.display="none"}}
updatePaginationSummary(startIndex,endIndex){const resultsLength=this.results.length;if(this.pageResultSummaryText)
this.pageResultSummaryText.textContent=(resultsLength>=1)?`Showing (${startIndex + 1} - ${endIndex}) of (${resultsLength}) results`:"No Results";if(this.pageIndexSummaryText)
this.pageIndexSummaryText.textContent=(resultsLength>=1)?`Page ${this.currentPage} of ${this.totalPages}`:"";if(this.pageProgressBar){const progressFill=this.pageProgressBar.querySelector(".progress-bar");const progress=Math.floor((resultsLength>=1)?(this.currentPage/this.totalPages)*100:0);this.pageProgressBar.setAttribute("aria-valuenow",progress);progressFill.style.width=`${progress}%`}}
updatePaginationControls(){this.pagePreviousBtn.disabled=this.currentPage===1;this.pageNextBtn.disabled=this.currentPage===this.totalPages}
resetSearch(){this.clearSearchInput();this.clearAllFilters()}
getClearToggleGroupBtn(groupName){return this.clearToggleGroupElements.find(clearBtn=>clearBtn.name===groupName)??null}
buildURLQuery(data){let searchParameters=new URLSearchParams(data);let emptyNullKeys=[];searchParameters.forEach((value,key)=>{if(value===''){emptyNullKeys.push(key)}});emptyNullKeys.forEach(key=>{searchParameters.delete(key)});return searchParameters.toString()}
buildURLEndpoint(){const basePath=window.location.pathname;const query=this.searchInputElement.value.toLowerCase().trim();const finalParameterObject={query,...this.activeFilters};const newQueries=`${this.buildURLQuery(finalParameterObject)}`;const endpoint=`${basePath}?${newQueries}`;window.history.replaceState(null,'',endpoint)}})